export function translate(lang: string, key: string, p?: Record<string, unknown> | null): string {
  const a = D[key]; let s: string;
  if (!a) s = key; else { const i = (LANGS as readonly string[]).indexOf(lang); s = a[i < 0 ? 1 : i] || a[1] || a[0] || key; }
  if (p) s = s.replace(/\{(\w+)\}/g, (m, k) => (p[k] != null ? String(p[k]) : m));
  return s;
}
export const fmtMoney = (v: number, cur: string, lang: string) => { try { return new Intl.NumberFormat(LOCALES[lang] ?? "en-GB", { style: "currency", currency: cur, maximumFractionDigits: 0 }).format(v || 0); } catch { return `${v} ${cur}`; } };
export const fmtDate = (d: string | number | Date | null | undefined, lang: string, o: Intl.DateTimeFormatOptions = { day: "numeric", month: "short", year: "numeric" }) => d ? new Intl.DateTimeFormat(LOCALES[lang] ?? "en-GB", o).format(new Date(d)) : "—";
